<script>
 import {onMount} from 'svelte';import {page} from '$app/stores';import {listSites,listScheduledTasks,createScheduledTask,setScheduledTaskEnabled,deleteScheduledTask} from '$lib/api.js';import {locale} from '$lib/i18n.js';import {notify} from '$lib/stores.js';import {formatDate} from '$lib/date.js';import Button from '$lib/components/Button.svelte';
 let sites=[],tasks=[],loading=true,saving=false,showCreate=false,selectedSite='',name='',command='',intervalMinutes='60',busy=0,error='';$:ru=$locale!=='en';$:projectId=$page.url.searchParams.get('project_id')||'';
 $:options=sites.map(x=>({key:String(x.device_id)+':'+String(x.site?.site_id||''),device_id:Number(x.device_id),site_id:x.site?.site_id||'',label:(x.site?.site_id||'Site')+' · '+(x.device_name||'Android host')})).filter(x=>x.site_id);
 $:selected=options.find(x=>x.key===selectedSite);$:enabled=tasks.filter(x=>x.enabled).length;
 async function load(){loading=true;error='';const r=await listSites(projectId);if(!r.ok){error=r.error||'Could not load applications';sites=[];tasks=[];loading=false;return}sites=r.data.sites||[];const targets=sites.map(x=>({key:String(x.device_id)+':'+String(x.site?.site_id||''),device_id:Number(x.device_id),site_id:x.site?.site_id||''})).filter(x=>x.site_id);const list=await Promise.all(targets.map(async x=>{const a=await listScheduledTasks(x.device_id,x.site_id);return a.ok?(a.data.tasks||[]):[]}));tasks=list.flat().sort((a,b)=>new Date(a.next_run_at)-new Date(b.next_run_at));if(!selectedSite&&targets.length)selectedSite=targets[0].key;loading=false}
 onMount(load);
 async function create(){if(!selected||!name.trim()||!command.trim())return;saving=true;const r=await createScheduledTask({device_id:selected.device_id,site_id:selected.site_id,name:name.trim(),command:command.trim(),interval_minutes:Number(intervalMinutes)});saving=false;if(!r.ok){notify(r.error||'Could not create schedule','error');return}notify(ru?'Расписание создано':'Schedule created','success');name='';command='';showCreate=false;await load()}
 async function toggle(x){busy=x.id;const r=await setScheduledTaskEnabled(x.id,!x.enabled);busy=0;if(!r.ok){notify(r.error||'Could not update task','error');return}tasks=tasks.map(t=>t.id===x.id?{...t,enabled:!x.enabled}:t)}
 async function remove(x){if(!confirm(ru?'Удалить расписание?':'Delete this schedule?'))return;busy=x.id;const r=await deleteScheduledTask(x.id);busy=0;if(!r.ok){notify(r.error||'Could not delete task','error');return}tasks=tasks.filter(t=>t.id!==x.id);notify(ru?'Расписание удалено':'Schedule deleted','success')}
 function interval(v){v=Number(v);return v%1440===0?(v/1440)+(ru?' дн.':' days'):v%60===0?(v/60)+(ru?' ч.':' hours'):v+(ru?' мин.':' min')}
</script>
<svelte:head><title>{ru?'Расписания · Yevqo':'Schedules · Yevqo'}</title></svelte:head>
<div class="page-header"><div><div class="eyebrow">OPERATIONS / AUTOMATION</div><h1 class="page-title">{ru?'Расписания':'Schedules'}</h1><p class="page-desc">{ru?'Периодические команды, выполняемые Agent на Android-устройствах.':'Recurring commands executed by the Agent on Android devices.'}</p></div><div class="actions"><Button on:click={load} disabled={loading}>{ru?'Обновить':'Refresh'}</Button><Button variant="primary" on:click={()=>showCreate=true} disabled={!options.length}>＋ {ru?'Создать задачу':'Create task'}</Button></div></div>
<div class="metrics"><article><span>{ru?'Всего задач':'Total tasks'}</span><strong>{tasks.length}</strong></article><article><span>{ru?'Включено':'Enabled'}</span><strong>{enabled}</strong></article><article><span>{ru?'Отключено':'Disabled'}</span><strong>{tasks.length-enabled}</strong></article></div>
{#if loading}<div class="empty">{ru?'Загружаем расписания…':'Loading schedules…'}</div>{:else if error}<div class="empty"><strong>{ru?'Не удалось загрузить':'Could not load schedules'}</strong><p>{error}</p><Button on:click={load}>{ru?'Повторить':'Retry'}</Button></div>{:else if !options.length}<div class="empty"><strong>{ru?'Нет приложений':'No applications'}</strong><p>{ru?'Сначала создай приложение в разделе Sites и подключи Android Agent.':'Create an application in Sites and connect an Android Agent first.'}</p><a href="/sites">{ru?'Открыть приложения →':'Open applications →'}</a></div>{:else if !tasks.length}<div class="empty"><strong>{ru?'Задачи ещё не запланированы':'No scheduled tasks yet'}</strong><p>{ru?'Создай периодическую команду для выбранного приложения.':'Create a recurring command for one of your applications.'}</p><Button variant="primary" on:click={()=>showCreate=true}>{ru?'Создать расписание':'Create schedule'}</Button></div>{:else}
<div class="task-list">{#each tasks as x (x.id)}<article class="task"><div class="task-main"><div class="task-title"><strong>{x.name}</strong><span class:enabled={x.enabled} class="state">{x.enabled?(ru?'Включено':'Enabled'):(ru?'Отключено':'Disabled')}</span></div><div class="meta">{x.site_id} · {options.find(o=>o.device_id===Number(x.device_id)&&o.site_id===x.site_id)?.label||'Android host'} · {interval(x.interval_minutes)}</div><pre>{x.command}</pre></div><div class="times"><span>{ru?'Следующий запуск':'Next run'}<b>{x.enabled?formatDate(x.next_run_at):'—'}</b></span><span>{ru?'Последний результат':'Last result'}<b>{x.last_status||'—'}</b></span>{#if x.last_error}<small>{x.last_error}</small>{/if}</div><div class="task-actions"><Button size="sm" disabled={busy===x.id} on:click={()=>toggle(x)}>{x.enabled?(ru?'Отключить':'Disable'):(ru?'Включить':'Enable')}</Button><Button size="sm" variant="danger" disabled={busy===x.id} on:click={()=>remove(x)}>{ru?'Удалить':'Delete'}</Button></div></article>{/each}</div>{/if}
{#if showCreate}<div class="backdrop" role="presentation" on:click={e=>{if(e.target===e.currentTarget)showCreate=false}}><section class="modal" role="dialog" aria-modal="true" aria-labelledby="schedule-title"><div class="modal-head"><h2 id="schedule-title">{ru?'Новое расписание':'New schedule'}</h2><button on:click={()=>showCreate=false} aria-label="Close">×</button></div><div class="field"><label for="task-site">{ru?'Приложение':'Application'}</label><select id="task-site" class="input" bind:value={selectedSite}>{#each options as o}<option value={o.key}>{o.label}</option>{/each}</select></div><div class="field"><label for="task-name">{ru?'Название задачи':'Task name'}</label><input id="task-name" class="input" bind:value={name} maxlength="100"/></div><div class="field"><label for="task-command">{ru?'Команда':'Command'}</label><textarea id="task-command" class="input" bind:value={command} rows="4" maxlength="4096" placeholder="php artisan schedule:run"/><small>{ru?'Команда выполняется на устройстве через Agent. Проверь её перед сохранением.':'The command runs on the device through the Agent. Review it before saving.'}</small></div><div class="field"><label for="task-interval">{ru?'Интервал':'Interval'}</label><select id="task-interval" class="input" bind:value={intervalMinutes}><option value="15">15 {ru?'минут':'minutes'}</option><option value="60">1 {ru?'час':'hour'}</option><option value="360">6 {ru?'часов':'hours'}</option><option value="1440">24 {ru?'часа':'hours'}</option><option value="10080">7 {ru?'дней':'days'}</option><option value="43200">30 {ru?'дней':'days'}</option></select><small>{ru?'Допустимый диапазон: 15 минут — 30 дней.':'Allowed range: 15 minutes — 30 days.'}</small></div><div class="modal-actions"><Button on:click={()=>showCreate=false}>{ru?'Отмена':'Cancel'}</Button><Button variant="primary" loading={saving} disabled={!selected||!name.trim()||!command.trim()} on:click={create}>{ru?'Создать':'Create'}</Button></div></section></div>{/if}
<style>
.actions{display:flex;gap:8px}.metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-bottom:14px}.metrics article{padding:14px 16px;background:var(--bg-card);border:1px solid var(--border);border-radius:8px}.metrics span{display:block;color:var(--text-muted);font-size:10px}.metrics strong{display:block;margin-top:6px;font-size:23px}.task-list{display:grid;gap:9px}.task{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(160px,.7fr) auto;gap:16px;align-items:center;padding:15px;background:var(--bg-card);border:1px solid var(--border);border-radius:8px}.task-title{display:flex;align-items:center;gap:9px;flex-wrap:wrap}.task-title strong{font-size:12px}.state{font-size:9px;padding:3px 7px;border-radius:20px;background:var(--bg-elevated);color:var(--text-muted)}.state.enabled{color:var(--success)}.meta{margin-top:5px;font-size:10px;color:var(--text-muted)}pre{margin-top:9px;padding:9px 10px;background:var(--bg-base);border:1px solid var(--border);border-radius:6px;white-space:pre-wrap;overflow-wrap:anywhere;font:10px/1.6 var(--mono)}.times{display:grid;gap:8px}.times span{display:grid;gap:2px;color:var(--text-muted);font-size:9px}.times b{color:var(--text-main);font-size:10px;font-weight:550}.times small{color:var(--danger);font-size:9px}.task-actions{display:flex;gap:6px;flex-wrap:wrap}.backdrop{position:fixed;inset:0;z-index:1000;display:grid;place-items:center;padding:18px;background:#020617B8}.modal{width:min(520px,100%);max-height:90vh;overflow:auto;padding:20px;background:var(--bg-card);border:1px solid var(--border);border-radius:10px;box-shadow:0 24px 80px #0008}.modal-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:15px}.modal-head h2{font-size:16px}.modal-head button{border:0;background:none;color:var(--text-muted);font-size:22px}.field{display:grid;gap:6px;margin:12px 0}.field label,.field small{font-size:10px;color:var(--text-muted)}.field textarea{resize:vertical;font-family:var(--mono)}.modal-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:18px}@media(max-width:900px){.task{grid-template-columns:1fr}.task-actions{justify-content:flex-end}}@media(max-width:700px){.metrics{grid-template-columns:1fr}.actions{width:100%}.actions :global(button){flex:1}}
</style>